# Reference distributions ------------------------------------------------------
# Loaded lazily from inst/extdata and cached for the session, so the defaults
# used by the generators and the simulation engine trace back to one file
# rather than being scattered as literals through the code.

.sdt_cache <- new.env(parent = emptyenv())

#' Reference distributions for the mass-casualty domain
#'
#' Returns the marginal distributions `sandtablR` calibrates against, read from
#' the file generated by `data-raw/tdsc_reference.R` and cached for the
#' session.
#'
#' The list separates three things that are easy to conflate:
#'
#' * `published` — marginals attributed to the TDSC tabletop evaluation
#'   (Achatz et al. 2023, \doi{10.1007/s00068-022-02217-1}). These are what the
#'   package reports and tests as "reference". Both evaluated versions of the
#'   exercise are carried; see `version`.
#' * `design` — the exercise as specified in that paper's Methods: duration,
#'   card count, team roles, and the nine-area board. Published, but structural
#'   rather than distributional.
#' * `defaults` — modelling choices made by `sandtablR` where the source does
#'   not pin a value (service times, routing probabilities, and so on). They
#'   are **not** attributed to the paper.
#'
#' Calibration tests use `published` only. Mixing the two would test the
#' package against its own assumptions.
#'
#' @param which Which part to return: `"all"`, `"published"`, `"design"`,
#'   `"defaults"` or `"meta"`.
#' @param version Which evaluated version of the exercise the published
#'   marginals should come from: `"2.0"` (the current exercise, the default) or
#'   `"1.0"` (its predecessor). Ignored for parts other than `"published"`,
#'   which are common to both.
#'
#' @return A named list.
#' @seealso [sdt_vocabularies] for the levels these marginals range over.
#' @export
#' @examples
#' sdt_reference("published")$triage_mix
#' sdt_reference("published", version = "1.0")$triage_mix
#'
#' # What the two versions did differently, side by side.
#' rbind(
#'   `2.0` = sdt_reference("published", "2.0")$end_state,
#'   `1.0` = sdt_reference("published", "1.0")$end_state
#' )
#'
#' sdt_reference("design")$duration
#' sdt_reference("meta")$doi
sdt_reference <- function(which = c("all", "published", "design", "defaults",
                                    "meta"),
                          version = c("2.0", "1.0")) {
  which <- rlang::arg_match(which)
  version <- rlang::arg_match(version)
  ref <- .tdsc_reference()
  ref$published <- ref$versions[[version]]
  if (identical(which, "all")) ref else ref[[which]]
}

.tdsc_reference <- function(call = rlang::caller_env()) {
  if (!is.null(.sdt_cache$reference)) {
    return(.sdt_cache$reference)
  }
  path <- system.file("extdata", "tdsc_reference.rds", package = "sandtablR")
  if (!nzchar(path) || !file.exists(path)) {
    cli::cli_abort(
      c(
        "Could not find the bundled reference distributions.",
        "i" = "Regenerate them with {.file data-raw/tdsc_reference.R}."
      ),
      call = call
    )
  }
  .sdt_cache$reference <- readRDS(path)
  .sdt_cache$reference
}

# Convenience accessors used across the package. Kept internal so the on-disk
# shape can change without breaking callers.
.ref_published <- function(name, version = "2.0") {
  .tdsc_reference()$versions[[version]][[name]]
}
.ref_default <- function(name) .tdsc_reference()$defaults[[name]]
.ref_design <- function(name) .tdsc_reference()$design[[name]]

# The published end-of-game locations, in board order.
.sdt_end_state_areas <- function() names(.ref_published("end_state"))

# Fold board areas onto the locations the paper reports. See the note on
# $defaults$end_state_map for the two pairings that are modelling choices.
.sdt_report_area <- function(x) {
  map <- .ref_default("end_state_map")
  out <- unname(map[x])
  ifelse(is.na(out), x, out)
}

#' The scenario the engine is calibrated on
#'
#' Builds the board configuration that [sdt_simulate()]'s defaults were tuned
#' against: a 40-casualty cohort on the resource capacities recorded in
#' `sdt_reference("defaults")$calibration`. Running it over the calibrated
#' horizon reproduces the published end-of-game distribution.
#'
#' Use it as a known-good starting point, and as the fixture the calibration
#' test checks, so that "the model still reproduces the reference" is a claim
#' someone can re-run rather than take on trust.
#'
#' @param seed Optional integer seed for the cohort. Defaults to the
#'   calibration seed.
#'
#' @return A `scenario` object.
#' @seealso [sdt_simulate()], [summary.game_run()].
#' @export
#' @examples
#' sc <- sdt_reference_scenario()
#' sc
#' run <- sdt_simulate(sc, replications = 2, seed = 1, verbose = FALSE)
#' summary(run, reference = TRUE)
sdt_reference_scenario <- function(seed = NULL) {
  cal <- .ref_default("calibration")
  seed <- .check_count(seed %||% cal$seed)
  cohort <- sdt_synthetic_cohort(n = cal$n, seed = seed)
  sdt_scenario(
    cohort,
    resources = cal$resources,
    name = "reference",
    seed = seed
  )
}

#' The horizon the engine is calibrated on
#'
#' @return A single number: the game length in minutes used for calibration.
#' @export
#' @examples
#' sdt_reference_horizon()
sdt_reference_horizon <- function() .ref_default("calibration")$horizon
